import{_ as t,o as n,c as o,ah as a}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Monitoring and control","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/administrateur/suivi.md","filePath":"src/en/guide/administrateur/suivi.md"}'),r={name:"en/guide/administrateur/suivi.md"};function i(s,e,l,c,d,g){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="monitoring-and-control" tabindex="-1">Monitoring and control <a class="header-anchor" href="#monitoring-and-control" aria-label="Permalink to &quot;Monitoring and control&quot;">​</a></h1><h2 id="seve-sync" tabindex="-1">Sève sync <a class="header-anchor" href="#seve-sync" aria-label="Permalink to &quot;Sève sync&quot;">​</a></h2><p><strong>Administration → Sève sync</strong> shows the calls Kura sends to Sève: opening the account, account status (active, suspended, Canopé), course enrolment, course removal.</p><p>Each call is <strong>pending</strong>, <strong>failing</strong> or <strong>sent</strong>. An account&#39;s calls go <strong>in order</strong>: a failing call holds back that account&#39;s following ones.</p><ul><li>A failure is <strong>retried</strong> automatically, at increasingly spaced intervals. The page shows the number of attempts and the next one.</li><li>At the <strong>fifth failure</strong> of a call, Administrators are <strong>alerted</strong>.</li><li><strong>Retry</strong> relaunches a call without waiting.</li><li>An account Moodle already knows is found, not created twice.</li><li>As long as Sève is not configured, calls wait, and the page says so.</li></ul><p>If a learner says they have no access to Sève, this is where you look to see if their account opening or course enrolment is blocked. A learner is only enrolled in a course if the Coordinator has entered <strong>the cohort&#39;s Sève course id</strong>.</p><h2 id="the-audit-log" tabindex="-1">The audit log <a class="header-anchor" href="#the-audit-log" aria-label="Permalink to &quot;The audit log&quot;">​</a></h2><p><strong>Administration → Audit log</strong> keeps all <strong>sensitive actions</strong>, in order: role approvals and withdrawals, account conversions, user edits, consent changes, signatures, certificate issuances, attendance corrections, and so on.</p><p>Each entry carries its date, <strong>action</strong>, <strong>author</strong> (or &quot;System&quot;), <strong>target</strong>, the <strong>channel</strong> and <strong>details</strong> (values before and after). Filter by action or author.</p><p><strong>The log cannot be modified</strong>: no entry is erased or corrected. The actions of privileged accounts (Coordinator, Direction, Administrator) on accounts and roles are always recorded there.</p><h2 id="deliveries-and-notification-failures" tabindex="-1">Deliveries and notification failures <a class="header-anchor" href="#deliveries-and-notification-failures" aria-label="Permalink to &quot;Deliveries and notification failures&quot;">​</a></h2><p>The <strong>deliveries log</strong> under <strong>Training → Communication</strong> shows what the notification engine sent, channel by channel, with failures (see <a href="./../coordinateur/communication.html#the-deliveries-log">Communication</a>). A failure on one channel does not stop the others.</p>',12)])])}const f=t(r,[["render",i]]);export{h as __pageData,f as default};
